from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

OUT = Path.home() / "DEV/drive-tools/drive-index"
FD = "00_Primary_Storage_Drive/99_UNSORTED/From_Desktop"
FOLDER = "application/vnd.google-apps.folder"


def gws(args, tries=3):
    """Parsed JSON of one gws drive files call, or None. tries=1 for a create: a retry could make a duplicate."""
    for _ in range(tries):
        r = subprocess.run(["gws", "drive", "files", *args], capture_output=True, text=True)
        if r.returncode:                 # a failed call is never read as an answer, even if it printed JSON (Codex)
            continue
        try:
            return json.loads(r.stdout)
        except ValueError:
            continue
    return None


def split(path):
    return path.rsplit("/", 1) if "/" in path else ("", path)


assert split("a/b/c") == ["a/b", "c"] and split("x") == ("", "x")   # top-level items have folder ""
def q_esc(s):
    """Drive query string literal: backslash and apostrophe escaped."""
    return s.replace("\\", "\\\\").replace("'", "\\'")


assert q_esc("Coach's \\x") == "Coach\\'s \\\\x"
