"""dates and drift: the Front Burner's self-checks (plan 2026-10-31, Phase 1 steps 4-5)."""
import datetime
import tempfile
import unittest
from pathlib import Path

import frontburner
import portfolio

TODAY = datetime.date(2026, 10, 31)


def row(name, status="active", lane="job", **extra):
    return {"name": name, "lane": lane, "rank": 1, "status": status,
            "purpose": "", "next_action": "", **extra}


def charter(*steps):
    return {"steps": [dict(name=n, due=d, done=done) for n, d, done in steps]}


class TestDates(unittest.TestCase):
    def test_every_overdue_step_on_every_active_row_is_listed_touched_or_not(self):
        data = {"projects": [
            row("A", charter=charter(("Plan agreed with receiver", "2026-10-02", None),
                                     ("First draft to receiver", "2026-10-09", None),
                                     ("Final delivered", "2026-11-20", None))),
            row("B", charter=charter(("Plan agreed with receiver", "2026-10-30", None))),
            row("P", status="paused", charter=charter(("Final delivered", "2026-10-01", None))),
        ]}
        got = frontburner.dates(data, TODAY)
        self.assertEqual([(i["project"], i["kind"]) for i in got],
                         [("A", "overdue"), ("A", "overdue"), ("B", "overdue")])
        self.assertTrue(all(i["needs_eric"] for i in got))

    def test_done_and_future_steps_are_fine(self):
        data = {"projects": [row("A", charter=charter(("Plan", "2026-10-02", "2026-10-03"),
                                                      ("Final", "2026-11-20", None)))]}
        self.assertEqual(frontburner.dates(data, TODAY), [])

    def test_a_row_with_neither_a_date_nor_no_hard_date_is_listed(self):
        data = {"projects": [row("A")]}
        self.assertEqual([i["kind"] for i in frontburner.dates(data, TODAY)], ["no_date"])

    def test_no_hard_date_clears_it_until_30_days_old(self):
        fresh = row("A", no_hard_date={"reason": "weekly capture", "source": "STATUS",
                                       "set_on": "2026-10-20"})
        old = row("B", no_hard_date={"reason": "waits on Mauro", "source": "STATUS",
                                     "set_on": "2026-09-01"})
        got = frontburner.dates({"projects": [fresh, old]}, TODAY)
        self.assertEqual([(i["project"], i["kind"]) for i in got], [("B", "stale_no_hard_date")])

    def test_finish_by_alone_is_not_a_date_a2(self):
        # A2: an open dated step or a no_hard_date record (inspection FB-12)
        for fb in ("2026-12-01", "2026-10-15"):
            with self.subTest(finish_by=fb):
                data = {"projects": [row("A", charter={"finish_by": fb, "steps": []})]}
                got = frontburner.dates(data, TODAY)
                self.assertEqual([i["kind"] for i in got], ["no_date"])
                self.assertIn(f"finish_by {fb}", got[0]["message"])

