class FakeGit:
    """Stands in for `git`: per-folder log dates, status output, or a failure."""

    def __init__(self, log=None, status=None, fail=None):
        self.log, self.status, self.fail = log or {}, status or {}, fail or {}

    def __call__(self, folder: Path, args: list[str]):
        key = (folder.name, args[0])
        if key in self.fail:
            return False, "", self.fail[key]
        if args[0] == "log":
            return True, "\n".join(self.log.get(folder.name, [])), ""
        return True, self.status.get(folder.name, ""), ""


class TestDrift(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name)

    def tearDown(self):
        self.tmp.cleanup()

    def repo(self, name):
        (self.root / name / ".git").mkdir(parents=True, exist_ok=True)
        return name

    def plain(self, name):
        (self.root / name).mkdir(parents=True)
        return name

    def run_drift(self, projects, git, ledger=()):
        return frontburner.drift({"projects": projects}, self.root, list(ledger), TODAY, 14, git)

    def kinds(self, report):
        return {(i["project"], i["kind"]) for i in report["items"]}

    def test_active_repo_with_no_commits_and_clean_tree_is_quiet(self):
        rep = self.run_drift([row("A", dev_folder=self.repo("A"))], FakeGit())
        self.assertEqual(self.kinds(rep), {("A", "quiet")})
        self.assertTrue(rep["items"][0]["needs_eric"])

    def test_uncommitted_changes_make_it_touched_not_quiet(self):
        rep = self.run_drift([row("A", dev_folder=self.repo("A"))],
                             FakeGit(status={"A": " M analysis.py"}))
        self.assertEqual(rep["states"]["A"]["state"], "touched")
        self.assertEqual(self.kinds(rep), set())

    def test_a_failed_git_command_is_unknown_never_quiet(self):
        for cmd in ("log", "status"):
            with self.subTest(cmd=cmd):
                rep = self.run_drift([row("A", dev_folder=self.repo("A"))],
                                     FakeGit(fail={("A", cmd): "fatal: bad object"}))
                self.assertEqual(self.kinds(rep), {("A", "cant_track")})
                self.assertIn("git " + cmd, rep["items"][0]["message"])

    def test_git_plus_drive_folder_says_drive_not_confirmed(self):
        rep = self.run_drift([row("A", dev_folder=self.repo("A"), drive_folder="X/A")], FakeGit())
        self.assertEqual(self.kinds(rep), {("A", "quiet")})
        self.assertIn("Drive not confirmed", rep["items"][0]["message"])

    def test_ledger_only_evidence_is_never_quiet(self):
        rep = self.run_drift([row("A", drive_folder="X/A")], FakeGit())
        self.assertEqual(self.kinds(rep), {("A", "cant_track")})
        self.assertIn("scan coverage unknown", rep["items"][0]["message"])

    def test_cant_track_reasons(self):
        rep = self.run_drift([row("NoFolder"), row("Gone", dev_folder="Gone"),
                              row("Plain", dev_folder=self.plain("Plain"))], FakeGit())
        msgs = {i["project"]: i["message"] for i in rep["items"]}
        self.assertIn("no folder mapped", msgs["NoFolder"])
        self.assertIn("folder missing", msgs["Gone"])
        self.assertIn("not a git repo", msgs["Plain"])
        self.assertFalse(any(i["needs_eric"] for i in rep["items"]))

    def test_off_board_work_needs_two_commit_days(self):
        rep = self.run_drift(
            [row("W", status="archived", dev_folder=self.repo("W")),
             row("T", status="paused", dev_folder=self.repo("T")),
             row("S", status="archived", lane="system", dev_folder=self.repo("S"))],
            FakeGit(log={"W": ["2026-10-29", "2026-10-30"], "T": ["2026-10-30"],
                         "S": ["2026-10-29", "2026-10-30"]}))
        self.assertEqual(self.kinds(rep), {("W", "off_board"), ("T", "off_board_weak")})
        need = {i["project"]: i["needs_eric"] for i in rep["items"]}
        self.assertEqual(need, {"W": True, "T": False})

    def test_a_no_answer_parks_the_row_out_of_drift_until_parked_until(self):
        log = {"W": ["2026-10-29", "2026-10-30"]}
        parked = row("W", status="archived", dev_folder=self.repo("W"), parked_until="2027-01-29")
        self.assertEqual(self.kinds(self.run_drift([parked], FakeGit(log=log))), set())
        lapsed = dict(parked, parked_until="2026-10-30")
        self.assertEqual(self.kinds(self.run_drift([lapsed], FakeGit(log=log))), {("W", "off_board")})

    def test_work_after_the_park_decision_resurfaces(self):
        # parked_until 2027-01-27 = decided 2026-10-29; a sweep row has no time of day, so the
        # whole decision day counts as new (errs toward asking); 10-28 is before it
        row_ = row("W", status="archived", dev_folder=self.repo("W"), parked_until="2027-01-27")
        rep = self.run_drift([row_], FakeGit(log={"W": ["2026-10-28", "2026-10-29", "2026-10-30"]}))
        self.assertEqual(self.kinds(rep), {("W", "off_board")})
