    if states[n]["state"] == "unknown":      # FB-2: the row's own failed inspection stays reported
        continue
    ks = [(c["name"], found[("child", c["name"])]) for c in kids[n]]
    best = max(ks, key=lambda x: rank.get(x[1]["state"], 0), default=None)
    if best and rank.get(best[1]["state"], 0) > rank.get(states[n]["state"], 0):
