row_since = {p["name"]: _since_for(p, window) for p in rows}
active = [p for p in rows if p.get("status") == "active"]
# FB-19: a merged row's repo still gets work; that work counts for its active parent (same window:
# _since_for gives every active row `window`). Children are inspected as active rows (dirty tree counts).
# shortcut: a merged child whose DEV folder is gone counts as retired (the usual end of a merge, e.g. the
# archived SoftwareTech_Mgmt_Framework); a live child repo that moves goes unwatched until its dev_folder
# is fixed. Upgrade to an explicit per-row watch flag if that bites.
kids = {p["name"]: [c for c in data.get("projects", []) if c.get("status") == "merged"
