import json,subprocess
def g(*a):
    r=subprocess.run(["gws","drive","files",*a],capture_output=True,text=True)
    return json.loads(r.stdout[r.stdout.index("{"):]) if r.returncode==0 and "{" in r.stdout else None
def path(i):
    p=[]
    while i and len(p)<12:
        m=g("get","--params",json.dumps({"fileId":i,"fields":"name,parents"}))
        if not m: break
        p.append(m["name"]); i=(m.get("parents") or [None])[0]
    return "/".join(reversed(p)).replace("My Drive/00_Primary_Storage_Drive/","")
def count(i,depth=0):
    n=0; tok=None; newest=""
    while True:
        p={"q":f"'{i}' in parents and trashed=false","fields":"nextPageToken,files(id,mimeType,modifiedTime)","pageSize":1000}
        if tok:p["pageToken"]=tok
        d=g("list","--params",json.dumps(p))
        for f in d["files"]:
            newest=max(newest,f["modifiedTime"][:10])
            if f["mimeType"].endswith("folder") and depth<4:
                c,nw=count(f["id"],depth+1); n+=c; newest=max(newest,nw)
            else: n+=1
        tok=d.get("nextPageToken")
        if not tok: return n,newest
targets={}
for fid in ("1ZXSbYY0792cyIjkj6Qxcq-1SBI1opdFy",):
    d=g("list","--params",json.dumps({"q":f"'{fid}' in parents and trashed=false","fields":"files(id,name)","pageSize":100}))
    for f in d["files"]:
        s=g("list","--params",json.dumps({"q":f"'{f['id']}' in parents and trashed=false and mimeType='application/vnd.google-apps.shortcut'","fields":"files(name,shortcutDetails)"}))
        for x in s["files"]: targets[x["shortcutDetails"]["targetId"]]=f["name"]
q="trashed=false and mimeType='application/vnd.google-apps.folder' and (name contains 'RTP Course' or name = 'Gemini_Projects' or name contains 'Victory' or name contains 'TypeSafe')"
for f in g("list","--params",json.dumps({"q":q,"fields":"files(id,name)","pageSize":50}))["files"]:
    targets.setdefault(f["id"],"(search) "+f["name"])
for tid,owner in targets.items():
    m=g("get","--params",json.dumps({"fileId":tid,"fields":"name,shared,mimeType"}))
    p=path(tid)
    if "_MACHINE" in p or "Computers" in p: continue
    n,nw=count(tid) if m["mimeType"].endswith("folder") else (1,"")
    print(f"{owner:<40} -> {p}  files={n} newest={nw} shared={m.get('shared')} id={tid}")
EOF

